/** Test-only passive Request/Response projection. No network, input, cookie/header reads or route substitution. */
import {openSync,closeSync,writeSync,readFileSync,lstatSync,realpathSync,constants} from 'node:fs'
import {join,dirname,basename,resolve} from 'node:path'
import {createHash} from 'node:crypto'
const digest=value=>createHash('sha256').update(value).digest('hex'),safeID=v=>typeof v==='string'&&v.length<=512&&/^[A-Za-z\d_.:-]+$/u.test(v)
const allowedOps=new Set(['status','frame','act','pause','takeover','resume','stop','preview','redock']),codes=new Set(['STALE_OBSERVATION','CONTROL_CHANGED','NOT_READY','DISABLED','APP_NOT_ALLOWED','DEVICE_BUSY','TARGET_CHANGED','QUEUE_FULL','FOCUS_CHANGED','HUMAN_INPUT_INTERRUPTED','INPUT_CLEANUP_FAILED','INVALID_ACTION','OUT_OF_BOUNDS','NATIVE_TIMEOUT','ABORTED'])
export function projectOwnedPreviewRequest(body,expectedSessionId){
 const p=body?.payload;if(body?.type!=='client-request'||body.method!=='qiuya-tools.computer.control'||!safeID(body.rpcId)||p?.sessionId!==expectedSessionId||!safeID(expectedSessionId)||!allowedOps.has(p.op))return null
 const a=p.request?.action;return {rpcId:body.rpcId,op:p.op,sessionId:expectedSessionId,...p.op==='act'?{actionIdSHA256:safeID(p.request?.actionId)?digest(p.request.actionId):null,frameIdSHA256:safeID(p.request?.frameId)?digest(p.request.frameId):null,kind:['type','key','click','drag','move','scroll'].includes(a?.kind)?a.kind:'other',textLength:typeof a?.text==='string'?a.text.length:null}: {}}
}
export function projectOwnedPreviewResponse(body,request){
 if(body?.type!=='server-response'||body.rpcId!==request?.rpcId)return null
 const result=body.result;return {op:request.op,sessionId:request.sessionId,rpcId:request.rpcId,ok:typeof result?.ok==='boolean'?result.ok:null,errorCode:result?.ok===false?(codes.has(result.error?.code)?result.error.code:'other'):null,...request.op==='frame'&&result?.ok===true?{frameIdSHA256:safeID(result.value?.frameId)?digest(result.value.frameId):null,width:Number.isFinite(result.value?.width)?result.value.width:null,height:Number.isFinite(result.value?.height)?result.value.height:null}: {}}
}
export function installOwnedPreviewRPCTrace({profileRoot,RequestType=Request,ResponseType=Response,onRecord}={}){
 if(typeof profileRoot!=='string'||basename(profileRoot)!=='qiuya-harness-home'||!/^qiuya-harness-e2e-[A-Za-z\d_-]+$/u.test(basename(dirname(profileRoot)))||resolve(profileRoot)!==profileRoot||realpathSync(profileRoot)!==profileRoot)throw Error('TRACE_OWN_PROFILE_REQUIRED')
 const info=lstatSync(profileRoot);if(!info.isDirectory()||info.isSymbolicLink()||info.uid!==process.getuid())throw Error('TRACE_OWN_PROFILE_REQUIRED')
 const registryKey=Symbol.for('qiuya.e2e.owned-preview-rpc.registry'),registry=globalThis[registryKey]??=new WeakMap(),byProfile=registry.get(RequestType)??new Map();registry.set(RequestType,byProfile);if(byProfile.has(profileRoot))return byProfile.get(profileRoot)
 const pending=new Map(),oldText=RequestType.prototype.text,oldJSON=ResponseType.json;let fd,sequence=0,closed=false,latestFrames=[],operations=0,statusReplies=0
 const mark=(phase,value)=>{if(closed)return;const row={sequence:++sequence,utcMs:Date.now(),monotonicNs:process.hrtime.bigint().toString(),phase,...value};onRecord?.(row);if(onRecord)return;if(fd===undefined)fd=openSync(join(profileRoot,'owned-preview-rpc-diagnostic.jsonl'),constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|constants.O_NOFOLLOW,0o600);if(sequence<=512)writeSync(fd,JSON.stringify(row)+'\n')}
 const expected=()=>{try{const file=join(profileRoot,'e2e-computer-target.json'),s=lstatSync(file);if(!s.isFile()||s.isSymbolicLink()||s.size>4096||s.uid!==process.getuid())return;const v=JSON.parse(readFileSync(file,'utf8'));return safeID(v.sessionId)?v.sessionId:undefined}catch{return undefined}}
 const tracedText=async function(){const value=await oldText.apply(this,arguments);try{const url=new URL(this.url);if(url.pathname!=='/api/qiuya-tools.computer.control'||url.search||url.hash||this.method!=='POST'||Buffer.byteLength(value)>256000)return value;const request=projectOwnedPreviewRequest(JSON.parse(value),expected());if(!request)return value;pending.set(request.rpcId,{request,start:performance.now()});if(pending.size>256)pending.delete(pending.keys().next().value);if(request.op!=='frame'&&request.op!=='status'){if(++operations<=64)mark('request-read',{...request,recentFrames:latestFrames.slice(-8)})}}catch{}return value}
 const tracedJSON=function(value){try{const pendingRequest=pending.get(value?.rpcId);if(pendingRequest){pending.delete(value.rpcId);const projected=projectOwnedPreviewResponse(value,pendingRequest.request);if(projected){if(projected.op==='frame'&&projected.ok===true){latestFrames.push({frameIdSHA256:projected.frameIdSHA256,utcMs:Date.now()});if(latestFrames.length>16)latestFrames.shift();if(latestFrames.length===1)mark('first-owned-frame-response',projected)}else if(projected.op==='status'){if(++statusReplies%16===0)mark('owned-status-hook-heartbeat',{sessionId:projected.sessionId,statusReplies})}else if(projected.op!=='status')mark('response-built',{...projected,elapsedMs:performance.now()-pendingRequest.start})}}}catch{}return oldJSON.apply(this,arguments)}
 RequestType.prototype.text=tracedText;ResponseType.json=tracedJSON
 const installed={stop(){if(closed)return;closed=true;byProfile.delete(profileRoot);if(RequestType.prototype.text===tracedText)RequestType.prototype.text=oldText;if(ResponseType.json===tracedJSON)ResponseType.json=oldJSON;if(fd!==undefined)closeSync(fd)},postsInput:0,requestsSent:0};byProfile.set(profileRoot,installed);return installed
}
